@GetMapping("/scenicspot/{id}")
@ApiOperation(value = "获取景点详情")
public CommonResult<TravelScenicDetailVo> scenicspotDetail(@PathVariable Long id) {

      TravelScenicDetailVo vo = travelScenicSpotService.selectDetailById(id);
      if (vo == null) {

            return CommonResult.fail().setResult("景点不存在");
      }
      return CommonResult.ok().setResult(vo);
}

