@PostMapping("/scanthing")
@ApiOperation(value = "拍照识别")
public CommonResult<ScanthingVo> scanthing(

            @RequestParam("file") MultipartFile file,
            @RequestParam(value = "lat", required = false) String lat,
            @RequestParam(value = "long", required = false) String lng,
            @RequestParam(value = "source", required = false) String source,
            @RequestParam(value = "sourceDetail", required = false) String sourceDetail) throws Exception {
      if (file == null || file.isEmpty()) {
            return CommonResult.fail().setResult("上传文件不能为空");
      }
      byte[] data = file.getBytes();
      String fileName = file.getOriginalFilename();
      String tag = "1";
      ScanthingVo vo = travelService.scanthing(tag, fileName, data, lng, lat,

                  source == null ? "scan" : source, sourceDetail);
      return CommonResult.ok().setResult(vo);
}

