@Transactional(rollbackFor = Throwable.class)
public Boolean storageRecognitionLibrary(TravelRecognitionLibrary travelRecognitionLibrary,

                                                              String[] tags, String userId) throws Exception {
      if (travelRecognitionLibrary.getId() == null) {

            travelRecognitionLibrary.setId(idWorker.nextId());
      }
      if (travelRecognitionLibrary.getSource() == null) {

            travelRecognitionLibrary.setSource(2);
      }
      travelRecognitionLibrary.setIsStorage(0);
      if (StringUtils.isNotBlank(userId)) {

            travelRecognitionLibrary.setCreateBy(String.valueOf(userId));
      }
      travelRecognitionLibrary.setCreateTime(new Date());
      byte[] imageBytes = readLocalUploadImage(travelRecognitionLibrary.getUrl());
      String contSign;
      if (imageBytes != null && imageBytes.length > 0) {

            contSign = baiduAIService.imageAdd(tags, travelRecognitionLibrary.getFilename(),
                        String.valueOf(travelRecognitionLibrary.getId()), imageBytes);

      } else {
            contSign = baiduAIService.imageAdd(tags, travelRecognitionLibrary.getFilename(),
                        String.valueOf(travelRecognitionLibrary.getId()), travelRecognitionLibrary.getUrl());

