      （5）附近景点 Service（距离计算与排序）

java
public TableDataInfo<TravelModuleDetail> getnear(String longitude, String latitude, int num, int size) {

      TableDataInfo<TravelModuleDetail> rspData = new TableDataInfo<>();
      rspData.setCode(HttpStatus.SUCCESS);
      rspData.setMsg("查询成功");
      TravelModuleDetail query = new TravelModuleDetail();
      query.setStatus(1);
      List<TravelModuleDetail> all = travelScenicSpotMapper.select(query);
      if (all == null || all.isEmpty()) {

            rspData.setRows(Collections.emptyList());
            rspData.setTotal(0);
            return rspData;
      }
      List<TravelModuleDetail> withDistance = new ArrayList<>();
      for (TravelModuleDetail detail : all) {
            String loc = detail.getLongitude();
            if (StringUtils.isBlank(loc)) continue;
            String[] parts = loc.split(",");
            if (parts.length != 2) continue;
            try {

                  String lat2 = parts[0].trim();
                  String lng2 = parts[1].trim();
                  String distance = getDistance(latitude, longitude, lat2, lng2, detail);
                  detail.setDistance(distance);
                  withDistance.add(detail);
            } catch (Exception e) {
                  log.warn("景点经纬度解析失败: {}", loc);
            }
      }
      withDistance.sort(Comparator.comparingInt(d -> parseDistanceToMeters(d.getDistance())));
      int total = withDistance.size();
      int from = Math.max(0, (num - 1) * size);
      int to = Math.min(from + size, total);

14

张钧益：建筑可阅读导览系统

      List<TravelModuleDetail> rows = (from >= total) ? Collections.emptyList()
                  : new ArrayList<>(withDistance.subList(from, to));

      rspData.setRows(rows);
      rspData.setTotal(total);
      return rspData;
}

      （6）文旅景点 Service（主表+详情表聚合保存）

java
@Transactional(rollbackFor = Exception.class)
public int add(TravelBizSpotSaveDto dto) {

      Long spotId = worker.nextId();
      TravelBizSpot spot = new TravelBizSpot();
      BeanUtils.copyProperties(dto, spot);
      spot.setId(spotId);
      spot.setCreateBy(SecurityUtils.getUsername());
      spot.setCreateTime(new Date());
      spotMapper.insertSelective(spot);
      TravelBizSpotDetail detail = new TravelBizSpotDetail();
      detail.setId(worker.nextId());
      detail.setSpotId(spotId);
      detail.setIntroHtml(dto.getIntroHtml());
      detail.setTrafficGuide(dto.getTrafficGuide());
      detail.setOpenTime(dto.getOpenTime());
      spotDetailMapper.insertSelective(detail);
      return 1;
}

      （7）百度 AI 相似图片搜索

